import React, { useState, useRef, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';

export default function StudentDashboard() {
  const { user, logout, API } = useAuth();
  const navigate = useNavigate();
  const videoRef = useRef(null);
  const [step, setStep] = useState('scan'); // scan | confirming | done
  const [scannedData, setScannedData] = useState(null);
  const [location, setLocation] = useState(null);
  const [geoStatus, setGeoStatus] = useState('');
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // ── Get user location on mount ────────────────
  useEffect(() => {
    if (!navigator.geolocation) {
      setError('Geolocation is not supported by your browser');
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
        setGeoStatus('✅ Location acquired');
      },
      () => {
        setGeoStatus('❌ GPS access denied. Enable location services.');
        setError('GPS location is required to mark attendance');
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  }, []);

  // ── Start camera scanning ─────────────────────
  const startScanning = async () => {
    setError('');
    setMessage('');
    setStep('scan');
    setScannedData(null);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment' },
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();
        // Simple QR scanning simulation — in production use a library
        scanLoop();
      }
    } catch (err) {
      setError('Camera access denied. Please allow camera permissions.');
    }
  };

  // ── Simulate QR scan (for demo) ───────────────
  // In production, use a library like `html5-qrcode` or `jsQR`
  const scanLoop = () => {
    // This is a placeholder. Real implementation would use
    // a QR scanning library to decode frames from the video.
    // For demo, we show a manual input fallback.
  };

  // ── Manual session ID input (fallback) ────────
  const [manualSessionId, setManualSessionId] = useState('');

  const handleManualSubmit = (e) => {
    e.preventDefault();
    if (!manualSessionId.trim()) return;
    setScannedData({ sessionId: manualSessionId.trim() });
    setStep('confirming');
  };

  // ── Mark attendance ───────────────────────────
  const markAttendance = async () => {
    if (!location) {
      setError('GPS location not available');
      return;
    }
    setLoading(true);
    setError('');
    try {
      const res = await API.post('/attendance/mark', {
        sessionId: scannedData.sessionId,
        lat: location.lat,
        lng: location.lng,
      });
      setMessage(res.data.message);
      setStep('done');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to mark attendance');
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => { logout(); navigate('/login'); };

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1>🎓 Student Dashboard</h1>
        <div>
          <span style={styles.userInfo}>{user?.name}</span>
          <button onClick={handleLogout} style={styles.logoutBtn}>Logout</button>
        </div>
      </div>

      <div style={styles.content}>
        {/* ── GPS Status ── */}
        <div style={styles.card}>
          <h2 style={styles.cardTitle}>📍 Location Status</h2>
          <p style={{ color: location ? '#6c63ff' : '#ff6b6b' }}>
            {geoStatus || 'Acquiring GPS...'}
          </p>
          {location && (
            <p style={{ fontSize: '0.8rem', color: '#888' }}>
              {location.lat.toFixed(6)}, {location.lng.toFixed(6)}
            </p>
          )}
        </div>

        {/* ── Step 1: Scan QR ── */}
        {step === 'scan' && (
          <div style={styles.card}>
            <h2 style={styles.cardTitle}>📷 Scan QR Code</h2>
            <p style={{ color: '#aaa', marginBottom: '12px' }}>
              Point your camera at the teacher's QR code
            </p>

            {/* Video element for camera preview */}
            <div style={styles.videoContainer}>
              <video ref={videoRef} style={styles.video} playsInline />
            </div>

            <button onClick={startScanning} style={styles.button}>
              📸 Start Camera
            </button>

            <div style={styles.divider}>
              <span style={styles.dividerText}>OR enter code manually</span>
            </div>

            <form onSubmit={handleManualSubmit} style={styles.form}>
              <input
                value={manualSessionId}
                onChange={(e) => setManualSessionId(e.target.value)}
                placeholder="Paste session ID from QR"
                style={styles.input}
              />
              <button type="submit" style={{ ...styles.button, background: '#555' }}>
                Use Session ID
              </button>
            </form>
          </div>
        )}

        {/* ── Step 2: Confirm Attendance ── */}
        {step === 'confirming' && (
          <div style={styles.card}>
            <h2 style={styles.cardTitle}>✅ Confirm Attendance</h2>
            <p>Session ID: <strong>{scannedData?.sessionId.slice(0, 20)}...</strong></p>
            {location && (
              <p style={{ fontSize: '0.85rem', color: '#aaa', margin: '8px 0' }}>
                📍 Your location will be verified against the classroom geo-fence
              </p>
            )}
            {error && <div style={styles.error}>{error}</div>}
            <div style={{ display: 'flex', gap: '12px', marginTop: '16px' }}>
              <button onClick={() => setStep('scan')} style={{ ...styles.button, background: '#555', flex: 1 }}>
                Cancel
              </button>
              <button onClick={markAttendance} disabled={loading} style={{ ...styles.button, flex: 1 }}>
                {loading ? 'Marking...' : '✅ Mark Present'}
              </button>
            </div>
          </div>
        )}

        {/* ── Step 3: Success ── */}
        {step === 'done' && (
          <div style={styles.card}>
            <h2 style={{ ...styles.cardTitle, color: '#6c63ff' }}>🎉 Attendance Marked!</h2>
            <p style={{ fontSize: '1.1rem', margin: '12px 0' }}>{message}</p>
            <button onClick={() => { setStep('scan'); setScannedData(null); setMessage(''); }} style={styles.button}>
              Scan Another QR
            </button>
          </div>
        )}

        {error && step !== 'confirming' && <div style={styles.error}>{error}</div>}
      </div>
    </div>
  );
}

const styles = {
  container: { minHeight: '100vh', padding: '20px' },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '30px',
    flexWrap: 'wrap',
    gap: '10px',
  },
  userInfo: { marginRight: '12px', color: '#a0a0c0' },
  logoutBtn: {
    padding: '8px 16px',
    borderRadius: '6px',
    border: '1px solid rgba(255,255,255,0.2)',
    background: 'transparent',
    color: '#ff6b6b',
    cursor: 'pointer',
  },
  content: { maxWidth: '500px', margin: '0 auto', display: 'flex', flexDirection: 'column', gap: '20px' },
  card: {
    background: 'rgba(255,255,255,0.06)',
    borderRadius: '12px',
    padding: '24px',
    backdropFilter: 'blur(10px)',
  },
  cardTitle: { marginBottom: '12px', fontSize: '1.2rem' },
  videoContainer: {
    background: '#000',
    borderRadius: '8px',
    overflow: 'hidden',
    marginBottom: '12px',
    minHeight: '200px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  },
  video: { width: '100%', maxHeight: '300px' },
  form: { display: 'flex', flexDirection: 'column', gap: '10px' },
  input: {
    padding: '10px 14px',
    borderRadius: '8px',
    border: '1px solid rgba(255,255,255,0.15)',
    background: 'rgba(255,255,255,0.06)',
    color: '#fff',
    fontSize: '0.95rem',
    outline: 'none',
  },
  button: {
    padding: '10px',
    borderRadius: '8px',
    border: 'none',
    background: '#6c63ff',
    color: '#fff',
    fontSize: '1rem',
    fontWeight: 600,
    cursor: 'pointer',
  },
  divider: {
    textAlign: 'center',
    margin: '16px 0',
    borderBottom: '1px solid rgba(255,255,255,0.1)',
    lineHeight: '0.1em',
  },
  dividerText: {
    background: '#24243e',
    padding: '0 10px',
    fontSize: '0.8rem',
    color: '#888',
  },
  error: {
    background: 'rgba(255,50,50,0.15)',
    padding: '10px',
    borderRadius: '8px',
    color: '#ff6b6b',
    fontSize: '0.9rem',
    textAlign: 'center',
    marginTop: '12px',
  },
};
